# PS5 evaluation and report. Students do not edit this file.
#
# `print_fund_report`, at the end of this file, runs the selected student functions on the model of
# each ticker (Study 1) and on the ticker's real monthly roll (Study 2). The function then writes
# Report.md to read and CSV files to explore. Exported values are decimals. Displayed tables show
# probabilities and premiums as percentages, and growth rates in 1/yr.
#
# The file reads from top to bottom:
#   1. Calling student functions
#   2. Statistics that allow missing values
#   3. Study 1: the model
#   4. Study 2: what happened
#   5. Summary tables
#   6. Display formats and table columns
#   7. Writing the report
#   8. Running the report
using CSV, DataFrames, Dates, Printf, Statistics, VLQuantitativeFinancePackage

# --- 1. Calling student functions ---------------------------------------------------------------

"""
    StudentCalls

A record of the student functions that the report called, so that the report can say which
functions failed and on which tickers.

### Fields

- `lookup`: A function that returns a student function from its name.
- `log`: For each student function, the tickers it was called on (`called`), the tickers where it
  failed (`failed`), and its first error message (`first`).
- `order`: The student functions in the order the report first called them.
"""
struct StudentCalls
    lookup::Function
    log::Dict{Symbol,Any}
    order::Vector{Symbol}
end

"""
    StudentCalls(lookup::Function) -> StudentCalls

Build an empty record that finds each student function with `lookup`.
"""
StudentCalls(lookup::Function) = StudentCalls(lookup, Dict{Symbol,Any}(), Symbol[]);

"""
    _StudentFailure

The marker that `_student` throws after it records an error, so that `_attempt` can tell a failed
student function from an error in the supplied code.
"""
struct _StudentFailure <: Exception end

"""
    _issue_text(caught) -> String

Return the first line of an error message, shortened to 300 characters, so that the report can
quote the error on one line.
"""
function _issue_text(caught)::String

    # The non-empty lines of the message (Base.strip: the course package has its own strip) -
    lines = filter(!isempty, Base.strip.(split(sprint(showerror, caught), '\n')));

    # Use the first line, or the type of the error when the message is empty -
    text = isempty(lines) ? string(typeof(caught)) : String(first(lines));

    # Shorten a long line -
    if length(text) > 300
        return first(text, 297) * "...";
    end
    return text;
end

"""
    _check_premium(v) -> Float64

Return `v` as a `Float64` when `v` is a positive, finite premium. Otherwise throw an error, so that
a wrong value is reported in the same way as a crash.
"""
function _check_premium(v)::Float64
    v isa Real && isfinite(v) && v > 0 ||
        throw(ArgumentError("it returned $(repr(v)), not a positive premium"));
    return Float64(v);
end

"""
    _check_month(v) -> NamedTuple

Return `v` as `(ratio, cash)` in `Float64` values when `v` is the `NamedTuple` that a month function
must return, with a positive wealth ratio and a finite cash amount. Otherwise throw an error.
"""
function _check_month(v)::NamedTuple
    (v isa NamedTuple && propertynames(v) == (:ratio, :cash)) ||
        throw(ArgumentError("it returned $(repr(v)), not a NamedTuple (ratio = ..., cash = ...)"));
    (v.ratio isa Real && isfinite(v.ratio) && v.ratio > 0) ||
        throw(ArgumentError("it returned the ratio $(repr(v.ratio)), not a positive wealth ratio"));
    (v.cash isa Real && isfinite(v.cash)) ||
        throw(ArgumentError("it returned the cash $(repr(v.cash)), not a finite amount"));
    return (ratio = Float64(v.ratio), cash = Float64(v.cash));
end

"""
    _check_rate(v) -> Float64

Return `v` as a `Float64` when `v` is a finite growth rate. Otherwise throw an error.
"""
function _check_rate(v)::Float64
    v isa Real && isfinite(v) ||
        throw(ArgumentError("it returned $(repr(v)), not a finite growth rate"));
    return Float64(v);
end

"""
    _student(calls, name, ticker, check, args...)

Call one student function by name on one ticker's data, and return the value after `check`
accepts it. On an error, record the error against the function and the ticker, keep the first
message, and throw `_StudentFailure`, so that the caller can leave that ticker's result missing.

### Arguments

- `calls`: The `StudentCalls` record of this report.
- `name`: The name of the student function.
- `ticker`: The ticker whose data the function receives.
- `check`: The function that checks the returned value.
- `args`: The arguments of the student function.
"""
function _student(calls::StudentCalls, name::Symbol, ticker::String, check::Function, args...)

    # Start a record the first time the report calls this function -
    if !haskey(calls.log, name)
        calls.log[name] = (called = Set{String}(), failed = Set{String}(), first = String[]);
        push!(calls.order, name);
    end
    record = calls.log[name];
    push!(record.called, ticker);

    # Call the function and check its value; invokelatest finds the function loaded after this file -
    try
        return check(Base.invokelatest(calls.lookup(name), args...));
    catch caught

        # Record the ticker and the first error message of this function -
        push!(record.failed, ticker);
        if isempty(record.first)
            push!(record.first, "($(ticker)): " * _issue_text(caught));
        end
        throw(_StudentFailure());
    end
end

"""
    _run_call_premium(calls, ticker, S, K, T, σ, gᵧ) -> Float64

Call the student's `call_premium` for one ticker and check the premium (USD/share).
"""
function _run_call_premium(calls::StudentCalls, ticker::String, S, K, T, σ, gᵧ)::Float64
    return _student(calls, :call_premium, ticker, _check_premium, S, K, T, σ, gᵧ);
end

"""
    _run_put_premium(calls, ticker, S, K, T, σ, gᵧ) -> Float64

Call the student's `put_premium` for one ticker and check the premium (USD/share).
"""
function _run_put_premium(calls::StudentCalls, ticker::String, S, K, T, σ, gᵧ)::Float64
    return _student(calls, :put_premium, ticker, _check_premium, S, K, T, σ, gᵧ);
end

"""
    _run_covered_call_month(calls, ticker, N_S, S_start, S_end, K, 𝒫, 𝒟, C) -> NamedTuple

Call the student's `covered_call_month` for one ticker and check its `(ratio, cash)`.
"""
function _run_covered_call_month(calls::StudentCalls, ticker::String, N_S, S_start, S_end, K, 𝒫, 𝒟, C)::NamedTuple
    return _student(calls, :covered_call_month, ticker, _check_month, N_S, S_start, S_end, K, 𝒫, 𝒟, C);
end

"""
    _run_collar_month(calls, ticker, N_S, S_start, S_end, K₁, K₂, 𝒫₁, 𝒫₂, 𝒟, C) -> NamedTuple

Call the student's `collar_month` for one ticker and check its `(ratio, cash)`.
"""
function _run_collar_month(calls::StudentCalls, ticker::String, N_S, S_start, S_end, K₁, K₂, 𝒫₁, 𝒫₂, 𝒟, C)::NamedTuple
    return _student(calls, :collar_month, ticker, _check_month, N_S, S_start, S_end, K₁, K₂, 𝒫₁, 𝒫₂, 𝒟, C);
end

"""
    _run_growth_rate(calls, ticker, ratios, T) -> Float64

Call the student's `growth_rate` for one ticker and check the growth rate (1/yr).
"""
function _run_growth_rate(calls::StudentCalls, ticker::String, ratios::Vector{Float64}, T)::Float64
    return _student(calls, :growth_rate, ticker, _check_rate, ratios, T);
end

"""
    _attempt(f::Function)

Run the calculation `f`, which calls student functions, and return its value. When a student
function fails, return `missing`, so that the report continues with the next calculation.
"""
function _attempt(f::Function)
    try
        return f();
    catch caught

        # A failed student function leaves this result missing; any other error is a real error -
        if caught isa _StudentFailure
            return missing;
        end
        rethrow();
    end
end

"""
    _call_issues(calls::StudentCalls) -> Vector{String}

Return one line for each student function that failed at least once. Each line gives the number
of tickers where the function failed and the function's first error message.
"""
function _call_issues(calls::StudentCalls)::Vector{String}

    # Initialize -
    issues = String[];

    # main loop: the student functions, in the order the report called them -
    for name in calls.order
        record = calls.log[name];

        # A function that never failed has nothing to report -
        if isempty(record.failed)
            continue;
        end

        # Say how many tickers failed, and quote the first error -
        n, m = length(record.failed), length(record.called);
        scope = n == m ? "all $m tickers" : "$n of $m tickers";
        push!(issues, "$(name) failed on $(scope). First error $(only(record.first))");
    end
    return issues;
end

# --- 2. Statistics that allow missing values ----------------------------------------------------

"""
    _present(v) -> Vector{Float64}

Return the values of `v` that are not `missing`.
"""
_present(v) = collect(Float64, skipmissing(v));

"""
    _column_mean(table, column::Symbol)

Return the mean of one column of a table, or `missing` when any value in the column is `missing`.
"""
function _column_mean(table::AbstractDataFrame, column::Symbol)
    column_values = table[!, column];
    if any(ismissing, column_values)
        return missing;
    end
    return mean(Float64.(column_values));
end

"""
    _path_statistics(rates) -> NamedTuple

Summarize the growth rates of a strategy on its simulated paths: the mean `mean`, the standard
deviation `sd`, and the probability `loss` that the growth rate is negative. All three values are
`missing` when `rates` is `missing`.
"""
function _path_statistics(rates)::NamedTuple
    if rates === missing
        return (mean = missing, sd = missing, loss = missing);
    end
    return (mean = mean(rates), sd = std(rates), loss = mean(rates .< 0));
end

"""
    _fund_statistics(fund, holding) -> NamedTuple

Summarize one fund's simulated paths.

### Arguments

- `fund`: The `(rates, borrowed)` of the fund's paths, or `missing`.
- `holding`: The growth rates of the holding benchmark on the same paths, or `missing`.

### Returns

- `(mean, sd, loss, beats, borrows)`: the three values of `_path_statistics`, the probability
  `beats` that the fund grows faster than the holding benchmark, and the probability `borrows`
  that the fund's cash ends a month negative. A value that needs a missing input is `missing`.
"""
function _fund_statistics(fund, holding)::NamedTuple

    # Every statistic needs the fund's paths -
    if fund === missing
        return (mean = missing, sd = missing, loss = missing, beats = missing, borrows = missing);
    end

    # The comparison with the holding benchmark also needs the benchmark's paths -
    statistics = _path_statistics(fund.rates);
    beats = holding === missing ? missing : mean(fund.rates .> holding);
    return (mean = statistics.mean, sd = statistics.sd, loss = statistics.loss, beats = beats,
        borrows = mean(fund.borrowed));
end

# --- 3. Study 1: the model ----------------------------------------------------------------------

# The wealth ratio of a simulated fund that is wiped out, a 99.9% loss. A fund whose wealth reaches
# zero or below has no growth rate, because the log of zero or a negative number is undefined.
const _WIPED_OUT_RATIO = 0.001;

"""
    _opening_cash(config, S::Float64) -> Float64

Return the opening cash (USD) of a fund, and of the holding benchmark, whose `N_S` shares cost `S`
each.
"""
_opening_cash(config::NamedTuple, S::Float64)::Float64 = config.cash_reserve * config.N_S * S;

"""
    _model_fund_rates(calls, ticker, S, target, σ, Δt, increment, config) -> NamedTuple

Run the covered call fund on every simulated path of one ticker. Each month the fund sells the
smallest listed strike at or above `target` times the share price, priced with the student's
`call_premium` at volatility `σ`. The student's `covered_call_month` runs the month, and the cash
carries from one month to the next. A path stops when the fund owes more than its shares are worth.

### Arguments

- `calls`: The `StudentCalls` record of this report.
- `ticker`: The ticker's symbol.
- `S`: The simulated share prices, from `monthly_prices` (USD/share).
- `target`: The target strike as a multiple of the share price.
- `σ`: The volatility that prices the calls (1/√yr).
- `Δt`: The length of a month in the model (years).
- `increment`: The spacing of the ticker's listed strikes (USD).
- `config`: The settings from `load_config`.

### Returns

- `(rates, borrowed)`: the growth rate of each path (1/yr), and whether the fund's cash ended any
  month negative on that path.
"""
function _model_fund_rates(calls::StudentCalls, ticker::String, S::Matrix{Float64}, target::Float64, σ::Float64,
    Δt::Float64, increment::Float64, config::NamedTuple)::NamedTuple

    # Initialize -
    number_of_months, number_of_paths = size(S, 1) - 1, size(S, 2);
    N_S, 𝒟, T = config.N_S, exp(config.gᵧ * Δt), number_of_months * Δt;
    rates = Vector{Float64}(undef, number_of_paths);
    borrowed = falses(number_of_paths);
    ratios = Vector{Float64}(undef, number_of_months);

    # main loop: one simulated path at a time -
    for p in 1:number_of_paths
        C = _opening_cash(config, S[1, p]); # cash at the start of the first month (USD)
        wiped_out = false; # true once the fund owes more than its shares are worth

        # one month at a time -
        for j in 1:number_of_months

            # Sell the listed strike at the target, at the student's premium -
            K = listed_call_strike(target * S[j, p], increment);
            𝒫 = _run_call_premium(calls, ticker, S[j, p], K, Δt, σ, config.gᵧ);

            # The fund's wealth at the end of this month, from the same inputs. At or below zero, the path stops -
            end_cash = 𝒟 * (C + N_S * 𝒫) - N_S * max(S[j+1, p] - K, 0.0);
            if N_S * S[j+1, p] + end_cash <= 0.0
                wiped_out = true;
                borrowed[p] = true;
                break;
            end

            # Run the month with the student's function, and carry the cash to the next month -
            month = _run_covered_call_month(calls, ticker, N_S, S[j, p], S[j+1, p], K, 𝒫, 𝒟, C);
            ratios[j] = month.ratio;
            C = month.cash;
            borrowed[p] |= C < 0;
        end

        # A wiped-out path counts as a 99.9% loss; any other path uses its monthly wealth ratios -
        if wiped_out
            rates[p] = _run_growth_rate(calls, ticker, [_WIPED_OUT_RATIO], T);
        else
            rates[p] = _run_growth_rate(calls, ticker, copy(ratios), T);
        end
    end
    return (rates = rates, borrowed = borrowed);
end

"""
    _model_collar_rates(calls, ticker, S, plan, Δt, increment, config) -> NamedTuple

Run the collar fund on every simulated path of one ticker. Each month the fund sells the same
listed call as the covered call fund, at the call's implied volatility, and buys the largest
listed put strike at or below the put's target, priced with the student's `put_premium` at the
put's implied volatility. The student's `collar_month` runs the month.

### Returns

- `(rates, borrowed)`: the growth rate of each path (1/yr), and whether the fund's cash ended any
  month negative on that path.
"""
function _model_collar_rates(calls::StudentCalls, ticker::String, S::Matrix{Float64}, plan::NamedTuple, Δt::Float64,
    increment::Float64, config::NamedTuple)::NamedTuple

    # Initialize -
    number_of_months, number_of_paths = size(S, 1) - 1, size(S, 2);
    N_S, 𝒟, T = config.N_S, exp(config.gᵧ * Δt), number_of_months * Δt;
    rates = Vector{Float64}(undef, number_of_paths);
    borrowed = falses(number_of_paths);
    ratios = Vector{Float64}(undef, number_of_months);

    # main loop: one simulated path at a time -
    for p in 1:number_of_paths
        C = _opening_cash(config, S[1, p]); # cash at the start of the first month (USD)

        # one month at a time -
        for j in 1:number_of_months

            # The listed strikes of this month's call and put -
            K₂ = listed_call_strike(plan.call_moneyness * S[j, p], increment);
            K₁ = listed_put_strike(plan.put_moneyness * S[j, p], increment);
            K₁ < K₂ || throw(ArgumentError("$(ticker): the put's listed strike is not below the call's."));

            # Price both options with the student's functions -
            𝒫₂ = _run_call_premium(calls, ticker, S[j, p], K₂, Δt, plan.call_iv, config.gᵧ);
            𝒫₁ = _run_put_premium(calls, ticker, S[j, p], K₁, Δt, plan.put_iv, config.gᵧ);

            # Run the month with the student's function, and carry the cash to the next month -
            month = _run_collar_month(calls, ticker, N_S, S[j, p], S[j+1, p], K₁, K₂, 𝒫₁, 𝒫₂, 𝒟, C);
            ratios[j] = month.ratio;
            C = month.cash;
            borrowed[p] |= C < 0;
        end
        rates[p] = _run_growth_rate(calls, ticker, copy(ratios), T);
    end
    return (rates = rates, borrowed = borrowed);
end

"""
    _model_holding_rates(calls, ticker, S, Δt, config) -> Vector{Float64}

Return the growth rate (1/yr) of the holding benchmark on every simulated path of one ticker. The
benchmark holds the same `N_S` shares and opening cash as the fund and sells no calls, so that the
benchmark's cash only grows by `𝒟` each month.
"""
function _model_holding_rates(calls::StudentCalls, ticker::String, S::Matrix{Float64}, Δt::Float64,
    config::NamedTuple)::Vector{Float64}

    # Initialize -
    number_of_months, number_of_paths = size(S, 1) - 1, size(S, 2);
    N_S, 𝒟, T = config.N_S, exp(config.gᵧ * Δt), number_of_months * Δt;
    rates = Vector{Float64}(undef, number_of_paths);
    ratios = Vector{Float64}(undef, number_of_months);

    # main loop: one simulated path at a time -
    for p in 1:number_of_paths
        B = _opening_cash(config, S[1, p]); # the benchmark's cash (USD)

        # The wealth ratio of each month; the cash grows at the risk-free rate -
        for j in 1:number_of_months
            ratios[j] = (N_S * S[j+1, p] + 𝒟 * B) / (N_S * S[j, p] + B);
            B = 𝒟 * B;
        end
        rates[p] = _run_growth_rate(calls, ticker, copy(ratios), T);
    end
    return rates;
end

"""
    _gap_step(N_S, S_before, S_after, 𝒟_gap, C) -> NamedTuple

Return the wealth ratio and the new cash over the days between one trade's expiration and the next
entry, when the fund holds its `N_S` shares and the fund's cash `C` grows by `𝒟_gap`.
"""
function _gap_step(N_S::Int, S_before::Float64, S_after::Float64, 𝒟_gap::Float64, C::Float64)::NamedTuple
    return (ratio = (N_S * S_after + 𝒟_gap * C) / (N_S * S_before + C), cash = 𝒟_gap * C);
end

"""
    _matched_rates(calls, roll, prices, config) -> NamedTuple

Run the fund and the holding benchmark on every simulated path of the real roll, for the
comparison of the model's promise with what happened. Each trade keeps its real target (its real
strike over the share price at entry), its real length, and its implied volatility. Each trade's
strike is the smallest listed strike at or above the target times the simulated price, and the
student's `call_premium` prices the call. Between trades the fund holds its shares and cash.

### Arguments

- `calls`: The `StudentCalls` record of this report.
- `roll`: One ticker's roll, from `ticker_rolls`.
- `prices`: The simulated prices of that roll, from `roll_prices`.
- `config`: The settings from `load_config`.

### Returns

- `(fund, holding)`: the growth rates (1/yr) of the fund and of the holding benchmark on each path.
"""
function _matched_rates(calls::StudentCalls, roll::NamedTuple, prices::NamedTuple, config::NamedTuple)::NamedTuple

    # Initialize -
    months = roll.months;
    ticker = roll.ticker;
    number_of_paths = size(prices.start, 2);
    N_S, gᵧ = config.N_S, config.gᵧ;
    fund = Vector{Float64}(undef, number_of_paths);
    holding = Vector{Float64}(undef, number_of_paths);

    # main loop: one simulated path at a time -
    for p in 1:number_of_paths
        C = _opening_cash(config, prices.start[1, p]); # the fund's cash (USD)
        B = C; # the holding benchmark's cash (USD)
        fund_ratios = Float64[];
        holding_ratios = Float64[];

        # one trade at a time -
        for (j, m) in enumerate(months)
            S_start, S_end = prices.start[j, p], prices.finish[j, p];

            # Between trades, the fund and the benchmark hold their shares and cash -
            if j > 1 && m.gap_days > 0
                𝒟_gap = exp(gᵧ * m.gap_days / PS5_CALENDAR_DAYS);
                fund_gap = _gap_step(N_S, prices.finish[j-1, p], S_start, 𝒟_gap, C);
                push!(fund_ratios, fund_gap.ratio);
                C = fund_gap.cash;
                holding_gap = _gap_step(N_S, prices.finish[j-1, p], S_start, 𝒟_gap, B);
                push!(holding_ratios, holding_gap.ratio);
                B = holding_gap.cash;
            end

            # The trade's length, and the growth of the cash over it -
            Δt = m.days / PS5_CALENDAR_DAYS;
            𝒟 = exp(gᵧ * Δt);

            # The fund sells the listed strike at the trade's real multiple of the simulated price -
            K = listed_call_strike((m.K_call / m.S_start) * S_start, roll.strike_increment);
            𝒫 = _run_call_premium(calls, ticker, S_start, K, Δt, m.call_iv, gᵧ);
            month = _run_covered_call_month(calls, ticker, N_S, S_start, S_end, K, 𝒫, 𝒟, C);
            push!(fund_ratios, month.ratio);
            C = month.cash;

            # The holding benchmark sells no calls, and its cash grows -
            push!(holding_ratios, (N_S * S_end + 𝒟 * B) / (N_S * S_start + B));
            B = 𝒟 * B;
        end

        # The growth rate of each strategy over the whole roll -
        fund[p] = _run_growth_rate(calls, ticker, fund_ratios, roll.T);
        holding[p] = _run_growth_rate(calls, ticker, holding_ratios, roll.T);
    end
    return (fund = fund, holding = holding);
end

"""
    evaluate_model(track, rolls, config, calls) -> NamedTuple

Study 1. For each ticker, simulate monthly share prices with geometric Brownian motion, using the
trailing drift and volatility on the ticker's first entry date, and run a fund that holds `N_S`
shares and a cash account and sells calls every month. Each month's strike is the smallest listed
strike at or above the first trade's strike multiple times the share price, on the ticker's grid of
listed strikes. A month lasts the first trade's time to expiration. The student's `call_premium`
prices the calls every month on every path, once at the trailing (historical) volatility and once
at the call's implied volatility. The Advanced collar fund also buys the largest listed put at or
below the put's strike multiple, priced with `put_premium` at the put's implied volatility. The
holding benchmark holds the same shares and opening cash and sells no calls.

### Arguments

- `track`: `standard` or `advanced`.
- `rolls`: The rolls of all tickers, from `ticker_rolls`.
- `config`: The settings from `load_config`.
- `calls`: The `StudentCalls` record of this report.

### Returns

`(tickers, strikes, differences)`:

- `tickers` has one row per ticker: `ticker, group, call_moneyness, σ̂, call_iv, premium_hist,
  premium_iv, premium_market` (first-trade premiums as fractions of the share price),
  `holding_mean, holding_sd, holding_loss` (mean, standard deviation, and probability of a negative
  growth rate of the holding benchmark), `fund_hist_mean, fund_hist_loss, fund_hist_beats,
  fund_hist_borrows`, the same four for `fund_iv` (`beats`: probability that the fund grows faster
  than the holding benchmark; `borrows`: probability that the fund's cash ends a month negative),
  `fund_iv_sd`, and `matched_beats`, the probability that the fund beats the holding benchmark when
  the simulation follows the real roll (each trade's real strike multiple, length, and implied
  volatility, and the gaps between trades). The Advanced track adds `put_moneyness, put_iv,
  put_premium_iv, collar_mean, collar_loss, collar_beats, collar_borrows, collar_sd`.
- `strikes` has one row per ticker and target strike multiple in the config's `moneyness_grid`,
  priced at the call's implied volatility: `ticker, moneyness, difference_mean` (mean of the fund
  minus holding growth rate), `beats`, `fund_loss`, `borrows`.
- `differences` maps each ticker to the simulated fund-minus-holding growth rates on the real roll,
  or `missing`.
"""
function evaluate_model(track::String, rolls::Vector{NamedTuple}, config::NamedTuple, calls::StudentCalls)::NamedTuple

    # Initialize -
    rows = NamedTuple[];
    strike_rows = NamedTuple[];
    differences = Dict{String,Any}();

    # main loop: one ticker at a time -
    for (index, roll) in enumerate(rolls)
        plan = roll.plan;
        ticker = roll.ticker;
        increment = roll.strike_increment;
        Δt = plan.term; # a month in the model lasts the first trade's time to expiration (years)
        S = monthly_prices(plan, length(roll.months), config, index);
        K = plan.call_moneyness * plan.S0; # the first trade's real strike (USD/share)

        # The first trade's premium as a fraction of the share price -
        premium_hist = _attempt(() -> _run_call_premium(calls, ticker, plan.S0, K, Δt, plan.σ̂, config.gᵧ) / plan.S0);
        premium_iv = _attempt(() -> _run_call_premium(calls, ticker, plan.S0, K, Δt, plan.call_iv, config.gᵧ) / plan.S0);

        # The holding benchmark: the same shares and opening cash, no calls -
        holding = _attempt(() -> _model_holding_rates(calls, ticker, S, Δt, config));

        # The fund, with the calls priced at each volatility -
        fund_hist = _attempt(() -> _model_fund_rates(calls, ticker, S, plan.call_moneyness, plan.σ̂,
            Δt, increment, config));
        fund_iv = _attempt(() -> _model_fund_rates(calls, ticker, S, plan.call_moneyness, plan.call_iv,
            Δt, increment, config));

        # Promise versus outcome: the real roll's strike multiples, lengths, and dates, with simulated share prices -
        matched = _attempt(() -> _matched_rates(calls, roll, roll_prices(roll, config, index), config));
        differences[ticker] = matched === missing ? missing : matched.fund .- matched.holding;

        # Summarize this ticker's paths -
        holding_statistics = _path_statistics(holding);
        hist_statistics = _fund_statistics(fund_hist, holding);
        iv_statistics = _fund_statistics(fund_iv, holding);
        row = (ticker = ticker, group = roll.group, call_moneyness = plan.call_moneyness, σ̂ = plan.σ̂,
            call_iv = plan.call_iv, premium_hist = premium_hist, premium_iv = premium_iv,
            premium_market = plan.call_fraction,
            holding_mean = holding_statistics.mean, holding_sd = holding_statistics.sd,
            holding_loss = holding_statistics.loss,
            fund_hist_mean = hist_statistics.mean, fund_hist_loss = hist_statistics.loss,
            fund_hist_beats = hist_statistics.beats, fund_hist_borrows = hist_statistics.borrows,
            fund_iv_mean = iv_statistics.mean, fund_iv_loss = iv_statistics.loss,
            fund_iv_beats = iv_statistics.beats, fund_iv_borrows = iv_statistics.borrows,
            fund_iv_sd = iv_statistics.sd,
            matched_beats = matched === missing ? missing : mean(matched.fund .> matched.holding));

        # Advanced: the collar fund, both options priced at their implied volatilities -
        if track == "advanced"
            put_iv = _attempt(() -> _run_put_premium(calls, ticker, plan.S0, plan.put_moneyness * plan.S0, Δt,
                plan.put_iv, config.gᵧ) / plan.S0);
            collar = _attempt(() -> _model_collar_rates(calls, ticker, S, plan, Δt, increment, config));
            collar_statistics = _fund_statistics(collar, holding);
            row = merge(row, (put_moneyness = plan.put_moneyness, put_iv = plan.put_iv,
                put_premium_iv = put_iv, collar_mean = collar_statistics.mean, collar_loss = collar_statistics.loss,
                collar_beats = collar_statistics.beats, collar_borrows = collar_statistics.borrows,
                collar_sd = collar_statistics.sd));
        end
        push!(rows, row);

        # The strike-choice table: the same paths, every target strike priced at the call's implied volatility -
        for m in config.moneyness_grid
            fund = _attempt(() -> _model_fund_rates(calls, ticker, S, m, plan.call_iv, Δt, increment, config));
            fund_statistics = _fund_statistics(fund, holding);
            difference_mean = (fund === missing || holding === missing) ? missing : mean(fund.rates .- holding);
            push!(strike_rows, (ticker = ticker, moneyness = m, difference_mean = difference_mean,
                beats = fund_statistics.beats, fund_loss = fund_statistics.loss, borrows = fund_statistics.borrows));
        end
    end

    return (tickers = DataFrame(rows), strikes = DataFrame(strike_rows), differences = differences);
end

# --- 4. Study 2: what happened ------------------------------------------------------------------

"""
    benchmark_closes(table, ticker, rolls) -> Dict{Date,Float64}

Check the daily closes of the market benchmark and return the closes by date (USD/share). Throws an
`ArgumentError` when the closes are for another ticker, or when a roll's first entry date or last
expiration date has no positive close.
"""
function benchmark_closes(table::DataFrame, ticker::AbstractString, rolls)::Dict{Date,Float64}

    # Check the columns and the ticker -
    issubset(["ticker", "date", "close"], names(table)) ||
        throw(ArgumentError("The benchmark closes must have the columns ticker, date, and close."));
    sort(unique(string.(table.ticker))) == [ticker] ||
        throw(ArgumentError("The benchmark closes are not for benchmark_ticker $(ticker)."));

    # Keep the positive closes -
    closes = Dict{Date,Float64}(d => Float64(c) for (d, c) in zip(table.date, table.close)
        if d isa Date && c isa Real && isfinite(c) && c > 0);

    # Every roll needs a close on its first entry date and on its last expiration date -
    for r in rolls, d in (r.first_entry, r.last_expiration)
        haskey(closes, d) || throw(ArgumentError("The benchmark closes have no $(ticker) close on $(d)."));
    end
    return closes;
end

"""
    _trade_growth(m, config) -> Float64

Return the factor by which cash grows at the risk-free rate over one real trade `m`.
"""
_trade_growth(m::NamedTuple, config::NamedTuple)::Float64 = exp(config.gᵧ * m.days / PS5_CALENDAR_DAYS);

"""
    _history_month(strategy, calls, ticker, m, C, config) -> NamedTuple

Run one strategy over one real trade, and return the trade's `(ratio, cash)`.

### Arguments

- `strategy`: `:fund_mid` sells the calls at their mid price, `:fund_bid` sells the calls at their
  bid, `:collar` also buys the put at its mid price, and `:holding` sells no calls.
- `calls`: The `StudentCalls` record of this report.
- `ticker`: The ticker's symbol.
- `m`: One trade of the ticker's roll, from `ticker_rolls`.
- `C`: The strategy's cash at the trade's entry (USD).
- `config`: The settings from `load_config`.
"""
function _history_month(strategy::Symbol, calls::StudentCalls, ticker::String, m::NamedTuple, C::Float64,
    config::NamedTuple)::NamedTuple

    # Initialize -
    N_S = config.N_S;
    𝒟 = _trade_growth(m, config);

    # The fund and the collar fund use the student's functions -
    if strategy == :fund_mid
        return _run_covered_call_month(calls, ticker, N_S, m.S_start, m.S_end, m.K_call, m.call_mid, 𝒟, C);
    elseif strategy == :fund_bid
        return _run_covered_call_month(calls, ticker, N_S, m.S_start, m.S_end, m.K_call, m.call_bid, 𝒟, C);
    elseif strategy == :collar
        return _run_collar_month(calls, ticker, N_S, m.S_start, m.S_end, m.K_put, m.K_call, m.put_mid, m.call_mid, 𝒟, C);
    end

    # The holding benchmark sells no calls, and its cash grows -
    return (ratio = (N_S * m.S_end + 𝒟 * C) / (N_S * m.S_start + C), cash = 𝒟 * C);
end

"""
    _history_ratios(strategy, calls, roll, config) -> NamedTuple

Return one strategy's wealth ratios over a ticker's real roll, in time order. Between an expiration
and a later entry, the strategy holds its shares and its cash grows.

### Returns

- `(ratios, negative_months)`: the wealth ratios, and the number of trades that end with negative
  cash.
"""
function _history_ratios(strategy::Symbol, calls::StudentCalls, roll::NamedTuple, config::NamedTuple)::NamedTuple

    # Initialize -
    N_S = config.N_S;
    C = _opening_cash(config, roll.months[1].S_start);
    ratios = Float64[];
    negative_months = 0;

    # main loop: one trade at a time -
    for (j, m) in enumerate(roll.months)

        # Hold the shares and the cash across a gap in dates or in closing prices -
        if j > 1
            previous = roll.months[j-1];
            if m.gap_days > 0 || m.S_start != previous.S_end
                𝒟_gap = exp(config.gᵧ * m.gap_days / PS5_CALENDAR_DAYS);
                gap = _gap_step(N_S, previous.S_end, m.S_start, 𝒟_gap, C);
                push!(ratios, gap.ratio);
                C = gap.cash;
            end
        end

        # Run this trade, and carry the cash to the next trade -
        month = _history_month(strategy, calls, roll.ticker, m, C, config);
        push!(ratios, month.ratio);
        C = month.cash;
        negative_months += C < 0;
    end
    return (ratios = ratios, negative_months = negative_months);
end

"""
    _history_rate(calls, roll, path)

Return the growth rate (1/yr) of one strategy over a ticker's real roll, from the output of
`_history_ratios`. The growth rate is `missing` when `path` is `missing` or the student's
`growth_rate` fails.
"""
function _history_rate(calls::StudentCalls, roll::NamedTuple, path)
    if path === missing
        return missing;
    end
    return _attempt(() -> _run_growth_rate(calls, roll.ticker, path.ratios, roll.T));
end

"""
    evaluate_history(track, rolls, closes, config, calls) -> DataFrame

Study 2. Replay each ticker's real monthly roll with a fund that holds `N_S` shares and a cash
account. On every trade the fund sells the calls at their mid price (and, for comparison, at their
bid), the premium goes into the cash, which earns the risk-free rate, and the calls settle at the
close on the expiration date. Between an expiration and a later entry the fund holds its shares and
its cash grows. The holding benchmark holds the same shares and opening cash and sells no calls.

### Arguments

- `track`: `standard` or `advanced`.
- `rolls`: The rolls of all tickers, from `ticker_rolls`.
- `closes`: The market benchmark's closes by date, from `benchmark_closes`.
- `config`: The settings from `load_config`.
- `calls`: The `StudentCalls` record of this report.

### Returns

One row per ticker: `ticker, group, first_entry, last_expiration, T` (years), `months`,
`months_called` (trades whose close at expiration was above the call's strike), `months_borrowed`
(months that end with the fund's cash negative), `premium_market` (average call mid price over the
share price at entry), `fund_g`, `fund_bid_g`, `holding_g`, `benchmark_g` (the market benchmark over
the same dates), `cash_g` (the risk-free rate), and `fund_beat` (`fund_g > holding_g`). The Advanced
track adds `collar_g`, `months_floored` (closes below the put's strike), `put_cost` (average put mid
over the share price), and `collar_beat`. Growth rates are in 1/yr, and are `missing` when a student
function failed.
"""
function evaluate_history(track::String, rolls::Vector{NamedTuple}, closes::AbstractDict, config::NamedTuple,
    calls::StudentCalls)::DataFrame

    # Initialize -
    rows = NamedTuple[];

    # main loop: one ticker at a time -
    for roll in rolls
        months = roll.months;

        # The fund at the mid and at the bid, and the holding benchmark -
        fund = _attempt(() -> _history_ratios(:fund_mid, calls, roll, config));
        fund_bid = _attempt(() -> _history_ratios(:fund_bid, calls, roll, config));
        holding = _history_ratios(:holding, calls, roll, config);

        # The growth rate of each strategy -
        fund_g = _history_rate(calls, roll, fund);
        fund_bid_g = _history_rate(calls, roll, fund_bid);
        holding_g = _history_rate(calls, roll, holding);

        # The market benchmark over this ticker's own dates -
        benchmark_g = log(closes[roll.last_expiration] / closes[roll.first_entry]) / roll.T;

        # A comparison with a missing growth rate is missing -
        row = (ticker = roll.ticker, group = roll.group, first_entry = roll.first_entry,
            last_expiration = roll.last_expiration, T = roll.T, months = length(months),
            months_called = count(m.S_end > m.K_call for m in months),
            months_borrowed = fund === missing ? missing : fund.negative_months,
            premium_market = mean(m.call_mid / m.S_start for m in months),
            fund_g = fund_g, fund_bid_g = fund_bid_g, holding_g = holding_g, benchmark_g = benchmark_g,
            cash_g = config.gᵧ, fund_beat = fund_g > holding_g);

        # Advanced: the collar fund at mid prices -
        if track == "advanced"
            collar = _attempt(() -> _history_ratios(:collar, calls, roll, config));
            collar_g = _history_rate(calls, roll, collar);
            row = merge(row, (collar_g = collar_g, months_floored = count(m.S_end < m.K_put for m in months),
                put_cost = mean(m.put_mid / m.S_start for m in months), collar_beat = collar_g > holding_g));
        end
        push!(rows, row);
    end
    return DataFrame(rows);
end

# --- 5. Summary tables --------------------------------------------------------------------------

"""
    summary_table(track, history, benchmark_ticker) -> DataFrame

The headline of Study 2: one row per strategy, with the average, median, lowest, and highest growth
rate over the tickers (1/yr). A fund's row also gives the number of tickers where the fund grew
faster than the holding benchmark (`beat_holding`). The rows are the covered call fund at mid
prices and at the bid, the collar fund (Advanced), and the benchmarks: holding the shares and cash,
the market benchmark, and cash.
"""
function summary_table(track::String, history::DataFrame, benchmark_ticker::AbstractString)::DataFrame

    # The strategies: the row's label, the column of growth rates, and whether the row is a fund -
    entries = [("Fund (mid prices)", :fund_g, true), ("Fund (calls sold at the bid)", :fund_bid_g, true)];
    if track == "advanced"
        push!(entries, ("Collar fund (mid prices)", :collar_g, true));
    end
    push!(entries, ("Holding: shares and cash, no calls", :holding_g, false));
    push!(entries, ("$(benchmark_ticker), price only", :benchmark_g, false));
    push!(entries, ("Cash (risk-free rate)", :cash_g, false));

    # main loop: one row per strategy -
    rows = NamedTuple[];
    for (label, column, is_fund) in entries
        rates = _present(history[!, column]);
        complete = length(rates) == nrow(history);
        holding_complete = !any(ismissing, history.holding_g);

        # The benchmarks are not compared with holding; a fund's count needs every growth rate -
        if !is_fund
            beat_count = "—";
        elseif complete && holding_complete
            beat_count = count(Float64.(history[!, column]) .> Float64.(history.holding_g));
        else
            beat_count = missing;
        end

        # The averages need every ticker's growth rate -
        push!(rows, (strategy = label, tickers = length(rates),
            avg_g = complete ? mean(rates) : missing, median_g = complete ? median(rates) : missing,
            lowest_g = complete ? minimum(rates) : missing, highest_g = complete ? maximum(rates) : missing,
            beat_holding = beat_count));
    end
    return DataFrame(rows);
end

"""
    model_summary(track, model) -> DataFrame

Study 1 averaged over the tickers: one row per strategy and pricing volatility, with the average
first-trade premium (fraction of the share price), the average of each ticker's mean growth rate
(1/yr), and the average probabilities that the growth rate is negative, that the fund beats the
holding benchmark, and that the fund's cash ends a month negative.
"""
function model_summary(track::String, model::DataFrame)::DataFrame

    # The holding benchmark and the fund at each volatility -
    rows = NamedTuple[
        (strategy = "Holding: shares and cash, no calls", premium = "—", mean_g = _column_mean(model, :holding_mean),
            loss = _column_mean(model, :holding_loss), beats = "—", borrows = "—"),
        (strategy = "Fund, calls at historical vol", premium = _column_mean(model, :premium_hist),
            mean_g = _column_mean(model, :fund_hist_mean), loss = _column_mean(model, :fund_hist_loss),
            beats = _column_mean(model, :fund_hist_beats), borrows = _column_mean(model, :fund_hist_borrows)),
        (strategy = "Fund, calls at implied vol", premium = _column_mean(model, :premium_iv),
            mean_g = _column_mean(model, :fund_iv_mean), loss = _column_mean(model, :fund_iv_loss),
            beats = _column_mean(model, :fund_iv_beats), borrows = _column_mean(model, :fund_iv_borrows))];

    # Advanced: the collar fund's premium is the call's premium minus the put's -
    if track == "advanced"
        push!(rows, (strategy = "Collar fund, at implied vol",
            premium = _column_mean(model, :premium_iv) - _column_mean(model, :put_premium_iv),
            mean_g = _column_mean(model, :collar_mean), loss = _column_mean(model, :collar_loss),
            beats = _column_mean(model, :collar_beats), borrows = _column_mean(model, :collar_borrows)));
    end
    return DataFrame(rows);
end

"""
    strike_summary(strikes) -> DataFrame

The strike-choice table averaged over the tickers: one row per target strike multiple, with the
average mean of the fund-minus-holding growth rate, and the average probabilities that the fund
beats the holding benchmark, that the fund loses money, and that the fund's cash ends a month
negative.
"""
function strike_summary(strikes::DataFrame)::DataFrame

    # main loop: one target strike multiple at a time, in increasing order -
    rows = NamedTuple[];
    for m in sort(unique(strikes.moneyness))
        tickers = strikes[strikes.moneyness .== m, :];
        push!(rows, (moneyness = m, difference_mean = _column_mean(tickers, :difference_mean),
            beats = _column_mean(tickers, :beats), fund_loss = _column_mean(tickers, :fund_loss),
            borrows = _column_mean(tickers, :borrows)));
    end
    return DataFrame(rows);
end

"""
    promise_table(model, history, differences) -> DataFrame

Promise versus outcome, one row per ticker: the model's probability that the fund beats the holding
benchmark on the real roll's strike multiples, implied volatilities, and dates (`model_beats`),
whether the fund did (`fund_beat`), the real fund-minus-holding growth rate (`difference`), and
where that difference falls among the simulated differences (`percentile`, the fraction of
simulated differences at or below the real difference).
"""
function promise_table(model::DataFrame, history::DataFrame, differences::AbstractDict)::DataFrame

    # main loop: the model's row and the history's row of each ticker -
    rows = NamedTuple[];
    for (m, h) in zip(eachrow(model), eachrow(history))

        # A missing growth rate gives a missing difference -
        difference = h.fund_g - h.holding_g;

        # Where the real difference falls among the simulated differences -
        simulated = differences[m.ticker];
        percentile = (difference === missing || simulated === missing) ? missing : mean(simulated .<= difference);

        push!(rows, (ticker = m.ticker, model_beats = m.matched_beats, fund_beat = h.fund_beat,
            difference = difference, percentile = percentile, holding_g = h.holding_g,
            months_called = h.months_called));
    end
    return DataFrame(rows);
end

# --- 6. Display formats and table columns -------------------------------------------------------

"""
    _shown(x::Real, digits::Int)

Round `x` for display, and turn a negative zero into zero, so that a value never prints as `-0.0`.
"""
function _shown(x::Real, digits::Int)
    v = round(x; digits = digits);
    return v == 0 ? zero(v) : v;
end

"""
    _text(x) -> String

Format a value as text, left aligned in a table. A missing value shows as `UNAVAILABLE`.
"""
_text(x)::String = ismissing(x) ? "UNAVAILABLE" : string(x);

"""
    _count(x) -> String

Format a count, right aligned in a table. A missing value shows as `UNAVAILABLE`.
"""
_count(x)::String = _text(x);

"""
    _rate(x) -> String

Format a probability as a percentage with one decimal. A missing value shows as `UNAVAILABLE`.
"""
_rate(x)::String = ismissing(x) ? "UNAVAILABLE" : @sprintf("%.1f%%", _shown(100 * x, 1));

"""
    _premium(x) -> String

Format a premium as a percentage with two decimals. A missing value shows as `UNAVAILABLE`.
"""
_premium(x)::String = ismissing(x) ? "UNAVAILABLE" : @sprintf("%.2f%%", _shown(100 * x, 2));

"""
    _g(x) -> String

Format a growth rate (1/yr) with its sign and three decimals. A missing value shows as `UNAVAILABLE`.
"""
_g(x)::String = ismissing(x) ? "UNAVAILABLE" : @sprintf("%+.3f", _shown(x, 3));

"""
    _multiple(x) -> String

Format a strike multiple with three decimals. A missing value shows as `UNAVAILABLE`.
"""
_multiple(x)::String = ismissing(x) ? "UNAVAILABLE" : @sprintf("%.3f", x);

"""
    _vol(x) -> String

Format a volatility with three decimals. A missing value shows as `UNAVAILABLE`.
"""
_vol(x)::String = ismissing(x) ? "UNAVAILABLE" : @sprintf("%.3f", x);

"""
    _yesno(x) -> String

Format a true or false value as `yes` or `no`. A missing value shows as `UNAVAILABLE`.
"""
function _yesno(x)::String
    if ismissing(x)
        return "UNAVAILABLE";
    elseif x
        return "yes";
    end
    return "no";
end

"""
    _premium_or_text(x) -> String

Format a premium as `_premium` does. A text entry, such as the dash of a value that does not apply,
shows as it is.
"""
_premium_or_text(x)::String = x isa AbstractString ? x : _premium(x);

"""
    _rate_or_text(x) -> String

Format a probability as `_rate` does. A text entry, such as the dash of a value that does not apply,
shows as it is.
"""
_rate_or_text(x)::String = x isa AbstractString ? x : _rate(x);

# The columns of each displayed table, in order: the header, the column of the data table, and the
# display format. A column formatted with `_text` is left aligned; every other column is right
# aligned. These are the tables of Report.md.
const _SUMMARY_COLUMNS = [
